INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "契丹入寇幽州，至易州定州而还", "start_year": 923, "end_year": 923, "time_original": "923年闰四月甲午", "dynasty": "五代十国", "description": "契丹入寇幽州，至易州定州而还。", "phases": [], "location_name": "幽州、易州、定州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "934a09a4-0967-5ba8-b8e5-9f6ba58c5053"}, {"title": "契丹屡掠馈运，幽州粮食不足半年，后唐面临压力", "start_year": 923, "end_year": 923, "time_original": "923年闰四月本段形势总述；各项开始日未详", "dynasty": "五代十国", "description": "契丹屡掠馈运，幽州粮食不足半年，后唐面临压力。", "phases": [], "location_name": "幽州、卫州、潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d51031b2-b0ee-578b-a0f6-3a59f3a9c847"}, {"title": "戴思远屯杨村，留卢顺密等守郓州", "start_year": null, "end_year": null, "time_original": "袭郓前部署，先是追叙；确年日未载", "dynasty": "五代十国", "description": "戴思远屯杨村，留卢顺密等守郓州。", "phases": [], "location_name": "杨村、郓州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "24a7a758-83cf-5432-b29c-d770ad39ddab"}, {"title": "卢顺密奔后唐，陈说郓州可袭取", "start_year": 923, "end_year": 923, "time_original": "923年闰四月壬寅出兵前；确日未载", "dynasty": "五代十国", "description": "卢顺密奔后唐，陈说郓州可袭取。", "phases": [], "location_name": "郓州、后唐", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fb9544ec-a194-5654-aff8-8cc9300413a1"}, {"title": "郭崇韬等反对远袭，李存勖与李嗣源密议出奇取郓", "start_year": 923, "end_year": 923, "time_original": "923年闰四月壬寅前", "dynasty": "五代十国", "desc