SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "契丹入寇幽州，至易州定州而还。", "citation": "卷272·同光元年（923）·zztj-v272-y0923-p010·原文件第15行", "note": "原文：甲午，契丹寇幽州，至易定而还。；核对说明：承闰月；此役主书未署领军人，不默认阿保机亲临；与春攻幽分开。", "status": "draft", "id": "3caa3e4d-1276-5a01-9745-b08e191b5ba3", "subject_id": "934a09a4-0967-5ba8-b8e5-9f6ba58c5053", "source_id": "fc7a4493-0de1-5d97-84b3-1121bf52bc5d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "923年闰四月甲午", "citation": "卷272·同光元年（923）·zztj-v272-y0923-p010·原文件第15行", "note": "原文：甲午，契丹寇幽州，至易定而还。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "c9b4d57e-144a-5851-8a13-dac925ac307c", "subject_id": "934a09a4-0967-5ba8-b8e5-9f6ba58c5053", "source_id": "fc7a4493-0de1-5d97-84b3-1121bf52bc5d"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》同记甲午契丹至易定而还。", "citation": "《旧五代史》卷二十九，段落 jiu-wudaishi-205deb4a7860-p000966；EPUB电子本，纸本及异文待核", "note": "原文：甲午，契丹寇幽州，至易、定而還。；核对说明：同闰月本纪印证；易定两州并非现代一个地名。", "status": "draft", "id": "484a8e18-eccb-5d31-9491-592335818f71", "subject_id": "934a09a4-0967-5ba8-b8e5-9f6ba58c5053", "source_id": "614c2137-a8c5-5a32-a74f-2a316635fb43"}, {"subject_table": "event", "field_path": "description", "claim_text": "契丹屡掠馈运，幽州粮食不足半年，后唐面临压力。", "citation": "卷272·同光元年（923）·zztj-v272-y0923-p010·原文件第15行", "note": "原文：时契丹屡入寇，钞掠馈运，幽州食不支半年，卫州为梁所取，潞州内叛，人情岌岌，以为梁未可取，帝患之。；核对说明：卫州取、潞州叛已有此前事件，此为汇总背景；不重复认作甲午攻占；以为梁未可取为当时判断。", "status": "draft", "id": "8fe85296-fefb-5f72-a35c-e132d73e8606", "subject_id": "d51031b2-b0ee-578b-a0f6-3a59f3a9c847", "source_id": "fc7a4493-0de1-5d97-84b3-1121bf52bc5d"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "923年闰四月本段形势总述；各项开始日未详", "citation": "卷272·同光元年（923）·zztj-v272-y0923-p010·原文件第15行", "note": "原文：时契丹屡入寇，钞掠馈运，幽州食不支半年，卫州为梁所取，潞州内叛，人情岌岌，以为梁未可取，帝患之。；核对说明：按主书及对应补证纪